import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`team member: remove tasks I added that are no longer needed`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a member removes their own task, it disappears from every teammate's view within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);

      // Node 0 adds a task
      await pageA.getByTestId('field-title').fill('Task to remove');
      await pageA.getByTestId('action-add_task').click();
      const taskOnA = pageA.getByTestId('item-task').filter({ hasText: 'Task to remove' });
      await expect(taskOnA).toBeVisible({ timeout: 5_000 });

      // Confirm node 1 can see it before removal
      await expect(
        pageB.getByTestId('item-task').filter({ hasText: 'Task to remove' })
      ).toBeVisible({ timeout: 5_000 });

      // Node 0 removes their own task
      await taskOnA.getByTestId('action-remove_task').click();

      // Task disappears from node 0
      await expect(taskOnA).toBeHidden({ timeout: 5_000 });

      // Task disappears from every teammate (node 1) within 5s
      await expect(
        pageB.getByTestId('item-task').filter({ hasText: 'Task to remove' })
      ).toBeHidden({ timeout: 5_000 });
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });

  test(`a member cannot remove tasks authored by someone else`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    try {
      // Node 1 creates a task (they are the author)
      await loginViaHash(pageB, 1);
      await pageB.getByTestId('field-title').fill('Node-1 owned task');
      await pageB.getByTestId('action-add_task').click();
      await expect(
        pageB.getByTestId('item-task').filter({ hasText: 'Node-1 owned task' })
      ).toBeVisible({ timeout: 5_000 });

      // Node 0 (a different member) sees the foreign task
      await loginViaHash(pageA, 0);
      const foreignTask = pageA.getByTestId('item-task').filter({ hasText: 'Node-1 owned task' });
      await expect(foreignTask).toBeVisible({ timeout: 5_000 });

      // Remove button should be disabled or absent — node 0 is not the author
      const removeBtn = foreignTask.getByTestId('action-remove_task');
      const removeBtnCount = await removeBtn.count();
      if (removeBtnCount > 0) {
        await expect(removeBtn).toBeDisabled();
      }
      // If count === 0, the button is absent, which also satisfies "cannot remove"
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });
});
